    public static string Get(string language, string key, params object[] args)
    {
        var pair = Strings[key];
        var text = language == "en" ? pair.En : pair.Ru;
        return args.Length == 0 ? text : string.Format(System.Globalization.CultureInfo.CurrentCulture, text, args);
    }

    // Service strings remain Russian at the source so changing language is reversible.
    public static string Translate(string language, string source)
    {
        if (language != "en") return source;
        foreach (var pair in Strings.Values)
            if (pair.Ru == source) return pair.En;
        if (ServiceTranslations.TryGetValue(source, out var translated)) return translated;
        foreach (var (ruStart, enStart, ruEnd, enEnd) in Patterns)
            if (source.StartsWith(ruStart, StringComparison.Ordinal) && source.EndsWith(ruEnd, StringComparison.Ordinal))
                return enStart + source.Substring(ruStart.Length, source.Length - ruStart.Length - ruEnd.Length) + enEnd;
        return source;
    }

